/// Reject filter, derived from the table above at comptime rather than emitted:
/// bit `len` of `NAME_LEN_MASK[first byte]` is set iff the table holds a name of
/// that length starting with that byte. Only 451 of the 1280 (first byte,
/// length) pairs the table's names could occupy actually are, so one load and
/// one bit test turns most `:looks_like_a_name:` runs away before the binary
/// search starts walking the table.
const NAME_LEN_MASK = blk: {
    @setEvalBranchQuota(15304);
    var mask = [_]u64{0} ** 256;
    for (EMOJI_MAP) |e| mask[e.name[0]] |= @as(u64, 1) << @intCast(e.name.len);
    break :blk mask;
};

/// Look up an emoji shortcode name (without the surrounding colons);
/// returns the emoji's UTF-8 bytes, or null if the name is unknown.
pub fn emoji_lookup(name: []const u8) ?[]const u8 {
    if (name.len == 0 or name.len > MAX_NAME_LEN) return null;
    if ((NAME_LEN_MASK[name[0]] >> @intCast(name.len)) & 1 == 0) return null;

    var lo: usize = 0;
    var hi: usize = EMOJI_MAP.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, name, EMOJI_MAP[mid].name)) {
            .eq => return EMOJI_MAP[mid].chars,
            .lt => hi = mid,
            .gt => lo = mid + 1,
        }
    }
    return null;
}
